#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_QUEUES 16
#define MAX_MSG_SIZE 65536
#define QUEUE_CAPACITY 256
#define ALIGNMENT 16

typedef struct {
    uint16_t msg_len;
    uint16_t flags;
    uint32_t sequence;
    uint8_t  hmac[32];
    uint8_t  payload[];
} message_frame_t;

typedef struct {
    uint8_t *buffer;
    size_t buf_size;
    size_t write_pos;
    size_t read_pos;
    uint32_t seq_counter;
    pthread_mutex_t lock;
    int active;
} secure_queue_t;

static secure_queue_t queues[MAX_QUEUES];
static pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

/* Compute aligned frame size for a given payload length */
static size_t compute_frame_size(uint16_t payload_len) {
    /* Frame header is fixed at 40 bytes (2+2+4+32) */
    size_t total = (size_t)payload_len + 40u;
    /* Align to 16-byte boundary for cache efficiency */
    size_t aligned = (total + (ALIGNMENT - 1)) & ~((size_t)(ALIGNMENT - 1));
    return aligned;
}

/* Initialize a queue with pre-allocated buffer */
int queue_init(int qid, size_t capacity_bytes) {
    if (qid < 0 || qid >= MAX_QUEUES) return -1;
    if (capacity_bytes == 0 || capacity_bytes > (size_t)1024 * 1024 * 64) return -1;

    pthread_mutex_lock(&global_lock);
    if (queues[qid].active) {
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    queues[qid].buffer = calloc(1, capacity_bytes);
    if (!queues[qid].buffer) {
        pthread_mutex_unlock(&global_lock);
        return -1;
    }
    queues[qid].buf_size = capacity_bytes;
    queues[qid].write_pos = 0;
    queues[qid].read_pos = 0;
    queues[qid].seq_counter = 0;
    queues[qid].active = 1;
    pthread_mutex_init(&queues[qid].lock, NULL);
    pthread_mutex_unlock(&global_lock);
    return 0;
}

/* Validate message before enqueueing */
static int validate_message(const uint8_t *data, size_t data_len) {
    if (!data || data_len == 0) return -1;
    if (data_len > MAX_MSG_SIZE) return -1;
    /* Check for null bytes in first 4 bytes (protocol requirement) */
    if (data_len >= 4) {
        for (int i = 0; i < 4; i++) {
            if (data[i] == 0x00) return -1;
        }
    }
    return 0;
}

/* Compute simple HMAC placeholder (in production, use real HMAC) */
static void compute_hmac(const uint8_t *data, size_t len, uint8_t *out) {
    /* Simplified keyed hash for demonstration */
    memset(out, 0, 32);
    for (size_t i = 0; i < len && i < 256; i++) {
        out[i % 32] ^= data[i];
        out[(i + 7) % 32] ^= (data[i] << 3) | (data[i] >> 5);
    }
}

/* Enqueue a message into the secure queue */
int queue_enqueue(int qid, const uint8_t *payload, uint16_t payload_len) {
    if (qid < 0 || qid >= MAX_QUEUES) return -1;
    if (validate_message(payload, payload_len) != 0) return -1;

    secure_queue_t *q = &queues[qid];
    pthread_mutex_lock(&q->lock);

    if (!q->active) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    size_t frame_size = compute_frame_size(payload_len);

    /* Check if we have space in the buffer */
    if (q->write_pos + frame_size > q->buf_size) {
        /* Try to wrap around */
        if (frame_size > q->read_pos) {
            pthread_mutex_unlock(&q->lock);
            return -1; /* Queue full */
        }
        q->write_pos = 0;
    }

    /* Write the frame */
    message_frame_t *frame = (message_frame_t *)(q->buffer + q->write_pos);
    frame->msg_len = payload_len;
    frame->flags = 0x0001; /* Valid message flag */
    frame->sequence = q->seq_counter++;

    /* Copy payload into frame */
    memcpy(frame->payload, payload, payload_len);

    /* Compute HMAC over header + payload */
    compute_hmac(q->buffer + q->write_pos, 40 + payload_len, frame->hmac);

    q->write_pos += frame_size;
    pthread_mutex_unlock(&q->lock);
    return 0;
}

/* Process incoming network data - parses length-prefixed messages */
int process_network_input(int qid, const uint8_t *netbuf, size_t netbuf_len) {
    if (!netbuf || netbuf_len < 2) return -1;

    size_t offset = 0;
    int count = 0;

    while (offset + 2 <= netbuf_len) {
        /* Read 16-bit big-endian length prefix */
        uint16_t msg_len = ((uint16_t)netbuf[offset] << 8) | netbuf[offset + 1];
        offset += 2;

        if (msg_len == 0) break; /* End marker */

        /* Validate we have enough data in network buffer */
        if (offset + msg_len > netbuf_len) return -1;

        /* Enqueue the message */
        if (queue_enqueue(qid, netbuf + offset, msg_len) == 0) {
            count++;
        }

        offset += msg_len;
    }

    return count;
}

/* Dequeue and process a message */
int queue_dequeue(int qid, uint8_t *out_buf, size_t out_buf_size, size_t *out_len) {
    if (qid < 0 || qid >= MAX_QUEUES) return -1;
    if (!out_buf || out_buf_size == 0 || !out_len) return -1;

    secure_queue_t *q = &queues[qid];
    pthread_mutex_lock(&q->lock);

    if (!q->active || q->read_pos == q->write_pos) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    message_frame_t *frame = (message_frame_t *)(q->buffer + q->read_pos);

    /* Verify frame integrity */
    if (frame->flags != 0x0001) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    uint16_t payload_len = frame->msg_len;

    /* Verify HMAC */
    uint8_t expected_hmac[32];
    uint8_t saved_hmac[32];
    memcpy(saved_hmac, frame->hmac, 32);
    memset(frame->hmac, 0, 32);
    compute_hmac(q->buffer + q->read_pos, 40 + payload_len, expected_hmac);
    memcpy(frame->hmac, saved_hmac, 32);

    if (memcmp(saved_hmac, expected_hmac, 32) != 0) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    /* Copy payload to output */
    if (payload_len > out_buf_size) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    memcpy(out_buf, frame->payload, payload_len);
    *out_len = payload_len;

    size_t frame_size = compute_frame_size(payload_len);
    q->read_pos += frame_size;

    pthread_mutex_unlock(&q->lock);
    return 0;
}

/* Batch copy operation - copies multiple messages into a contiguous output buffer */
int batch_dequeue(int qid, uint8_t *out_buf, size_t out_buf_size, int max_messages) {
    if (qid < 0 || qid >= MAX_QUEUES) return -1;
    if (!out_buf || out_buf_size == 0) return -1;
    if (max_messages <= 0 || max_messages > 1024) return -1;

    secure_queue_t *q = &queues[qid];
    pthread_mutex_lock(&q->lock);

    if (!q->active) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }

    int count = 0;
    size_t out_offset = 0;

    while (count < max_messages && q->read_pos != q->write_pos) {
        message_frame_t *frame = (message_frame_t *)(q->buffer + q->read_pos);

        if (frame->flags != 0x0001) break;

        uint16_t payload_len = frame->msg_len;

        /* Calculate space needed: 2-byte length prefix + payload */
        size_t space_needed = (size_t)2 + (size_t)payload_len;

        /* Check output buffer space */
        if (out_offset + space_needed > out_buf_size) break;

        /* Write length prefix */
        out_buf[out_offset] = (payload_len >> 8) & 0xFF;
        out_buf[out_offset + 1] = payload_len & 0xFF;
        out_offset += 2;

        /* Copy payload */
        memcpy(out_buf + out_offset, frame->payload, payload_len);
        out_offset += payload_len;

        size_t frame_size = compute_frame_size(payload_len);
        q->read_pos += frame_size;
        count++;
    }

    pthread_mutex_unlock(&q->lock);
    return count;
}

void queue_destroy(int qid) {
    if (qid < 0 || qid >= MAX_QUEUES) return;
    pthread_mutex_lock(&global_lock);
    if (queues[qid].active) {
        pthread_mutex_lock(&queues[qid].lock);
        free(queues[qid].buffer);
        queues[qid].buffer = NULL;
        queues[qid].active = 0;
        queues[qid].buf_size = 0;
        pthread_mutex_unlock(&queues[qid].lock);
        pthread_mutex_destroy(&queues[qid].lock);
    }
    pthread_mutex_unlock(&global_lock);
}

int main(void) {
    /* Initialize queue with 4KB buffer */
    if (queue_init(0, 4096) != 0) {
        fprintf(stderr, "Failed to init queue\n");
        return 1;
    }

    /* Simulate receiving network data */
    uint8_t netdata[128];
    memset(netdata, 'A', sizeof(netdata));
    /* Length prefix: 100 bytes */
    netdata[0] = 0x00;
    netdata[1] = 0x64;
    /* Ensure no null in first 4 payload bytes */
    netdata[2] = 'H'; netdata[3] = 'E'; netdata[4] = 'L'; netdata[5] = 'L';

    process_network_input(0, netdata, sizeof(netdata));

    /* Dequeue */
    uint8_t output[256];
    size_t out_len;
    if (queue_dequeue(0, output, sizeof(output), &out_len) == 0) {
        printf("Dequeued %zu bytes\n", out_len);
    }

    queue_destroy(0);
    return 0;
}
